  const dir=temp(),config={googleClientId:"client",googleClientSecret:"secret",googleLoginRedirectUri:"https://noema.test/api/v1/auth/google/callback",ownerEmail:"owner@example.com",sessionHours:720},{openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),collaboration=await import("../server/collaboration.mjs"),google=await import("../server/google-sign-in.mjs"),db=openDatabase(join(dir,"test.sqlite"));
