test("Google Calendar OAuth encrypts tokens and persists selected calendars",async()=>{
  const dir=temp(),key="test-encryption-key-with-more-than-32-characters",config={googleClientId:"client",googleClientSecret:"secret",googleRedirectUri:"https://noema.test/api/v1/integrations/google/callback",appEncryptionKey:key};const {openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),google=await import("../server/google-calendar.mjs"),db=openDatabase(join(dir,"test.sqlite"));
  try{const user=await auth.ensureOwner({email:"owner@example.com",password:"correct horse battery staple"},db),begin=google.beginGoogleOAuth(user.id,config,db),state=new URL(begin.authorizationUrl).searchParams.get("state");let refreshed=false,revoked=false;const fake=async(input,init={})=>{const url=String(input);if(url.endsWith("/token")&&String(init.body).includes("authorization_code"))return Response.json({access_token:"access-one",refresh_token:"refresh-secret",expires_in:3600,scope:"openid https://www.googleapis.com/auth/calendar"});if(url.endsWith("/token")){refreshed=true;return Response.json({access_token:"access-two",expires_in:3600})}if(url.includes("userinfo"))return Response.json({email:"owner@gmail.com"});if(url.includes("calendarList")&&url.includes("pageToken"))return Response.json({items:[{id:"work",summary:"Work",timeZone:"Asia/Jakarta",accessRole:"writer"}]});if(url.includes("calendarList"))return Response.json({items:[{id:"primary",summary:"Personal",timeZone:"Asia/Jakarta",accessRole:"owner"}],nextPageToken:"next"});if(url.includes("revoke")){revoked=true;return new Response(null,{status:200})}throw new Error(`Unexpected fake Google request: ${url}`)};
    const connected=await google.completeGoogleOAuth(user.id,state,"code",config,db,fake);assert.equal(connected.email,"owner@gmail.com");const stored=db.prepare("SELECT token_enc FROM google_accounts WHERE user_id=?").get(user.id).token_enc;assert.doesNotMatch(stored,/access-one|refresh-secret/);assert.equal(db.prepare("SELECT COUNT(*) AS count FROM google_oauth_states").get().count,0);await assert.rejects(()=>google.completeGoogleOAuth(user.id,state,"code",config,db,fake),/invalid or expired/);
    let calendars=await google.discoverGoogleCalendars(user.id,config,db,fake);assert.deepEqual(calendars.map(item=>item.id),["primary","work"]);calendars=google.selectGoogleCalendars(user.id,["primary","work"],db);assert.equal(calendars.filter(item=>item.selected).length,2);assert.throws(()=>google.selectGoogleCalendars(user.id,["unknown"],db),/Unknown/);db.prepare("UPDATE google_accounts SET expires_at=? WHERE user_id=?").run("2000-01-01T00:00:00.000Z",user.id);await google.discoverGoogleCalendars(user.id,config,db,fake);assert.equal(refreshed,true);await google.revokeGoogle(user.id,config,db,fake);assert.equal(revoked,true);assert.equal(google.googleStatus(user.id,db).connected,false)
  }finally{db.close();rmSync(dir,{recursive:true,force:true})}
});

