test("mixed note blocks round-trip SVG, JSON, PNG, order, and corrected OCR",async()=>{const dir=temp(),vaultDir=join(dir,"vault");mkdirSync(vaultDir);writeFileSync(join(vaultDir,"Sketch.md"),"# Sketch\n\nTyped first\n");const {openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),collaboration=await import("../server/collaboration.mjs"),vault=await import("../server/vault.mjs"),{strokesToPng}=await import("../server/ink-raster.mjs"),core=await import("../server/core.mjs"),db=openDatabase(join(dir,"test.sqlite"));try{const user=await auth.ensureOwner({email:"ink@example.com",password:"correct horse battery staple"},db),workspace=collaboration.ensureDefaultWorkspace(user.id,db),actor={id:user.id,workspaceId:workspace.id},source=vault.connectVault({rootPath:vaultDir},workspace.id,db);vault.scanVault(source.id,actor,db);const note=core.listState(db,workspace.id).notes[0],stroke={id:"s1",tool:"pen",color:"#112233",width:3,points:[{x:10,y:10,pressure:.5,time:1,tiltX:4,tiltY:0},{x:40,y:30,pressure:.7,time:2,tiltX:5,tiltY:1}]},saved=vault.saveInkBlock(note.id,{id:"ink-1",width:100,height:50,strokes:[stroke]},actor,db);assert.equal(saved.version,1);assert.match(readFileSync(join(vaultDir,"Sketch.md"),"utf8"),/noema:ink:ink-1[\s\S]*!\[\[Attachments\/Noema Ink\/ink-1\.svg\]\]/);assert.deepEqual(JSON.parse(readFileSync(join(vaultDir,"Attachments/Noema Ink/ink-1.json"),"utf8")).strokes,[stroke]);assert.equal(strokesToPng({width:100,height:50,strokes:[stroke]}).subarray(1,4).toString(),"PNG");let blocks=vault.listNoteBlocks(note.id,actor,db);assert.deepEqual(blocks.map(block=>block.kind),["markdown","ink"]);blocks=vault.reorderNoteBlocks(note.id,{ids:["ink-1",blocks[0].id]},actor,db);assert.equal(blocks[0].id,"ink-1");vault.updateInkTranscript("ink-1",{transcript:"quantum handwritten theorem",equations:[{latex:"x^2",confidence:"high"}],version:1},actor,db);assert.equal(core.searchNotes("quantum",db,workspace.id)[0].id,note.id);assert.throws(()=>vault.saveInkBlock(note.id,{id:"ink-1",width:100,height:50,strokes:[],version:1},actor,db),error=>error.status===409)}finally{db.close();rmSync(dir,{recursive:true,force:true})}});

