test("vault tasks rewrite complete lines, retain identity across files, and stay out of Google sync",async()=>{const dir=temp(),vaultDir=join(dir,"vault"),todo=join(vaultDir,"TODO","2026");mkdirSync(todo,{recursive:true});writeFileSync(join(todo,"July.md"),"Before\r\n- [ ] Draft [[Plan]] 29 Jul 09:30 #remind30 #keep\r\nAfter\r\n");const {openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),collaboration=await import("../server/collaboration.mjs"),core=await import("../server/core.mjs"),vault=await import("../server/vault.mjs"),db=openDatabase(join(dir,"test.sqlite"));try{const user=await auth.ensureOwner({email:"owner@example.com",password:"correct horse battery staple"},db),workspace=collaboration.ensureDefaultWorkspace(user.id,db),actor={id:user.id,workspaceId:workspace.id},source=vault.connectVault({rootPath:vaultDir},workspace.id,db);vault.scanVault(source.id,actor,db);vault.scanVault(source.id,actor,db);core.saveEvent({title:"Calendar event",startAt:"2026-07-29T04:00:00.000Z",endAt:"2026-07-29T05:00:00.000Z",timezone:"Asia/Jakarta"},db,actor);let state=core.listState(db,workspace.id),task=state.tasks[0],id=task.id;assert.equal(task.vaultSource.relativePath,"TODO/2026/July.md");assert.equal(state.calendarItems.filter(item=>item.kind==="task"&&item.task.id===id).length,1);assert.equal(state.calendarItems.filter(item=>item.kind==="event").length,1);core.saveTask({...task,title:"Review [[Plan]] #keep",scheduledStartAt:"2026-07-30T03:15:00.000Z",dueAt:"2026-07-30T03:15:00.000Z",reminderAt:"2026-07-30T02:30:00.000Z",completed:true,version:task.version},db,actor);let content=readFileSync(join(todo,"July.md"),"utf8");assert.match(content,/^Before\r\n- \[x\] Review \[\[Plan\]\] #keep 30 Jul 10:15 #remind45 \^noema-[a-f0-9]+\r\nAfter\r\n$/);assert.equal(db.prepare("SELECT content FROM notes WHERE id=?").get(task.vaultSource.noteId).content,content);assert.equal(vault.scanVault(source.id,actor,db).written,0);const line=content.split(/\r?\n/)[1];writeFileSync(join(todo,"July.md"),"Before\r\nAfter\r\n");writeFileSync(join(todo,"Moved.md"),`# Moved\n${line}\n`);vault.scanVault(source.id,actor,db);state=core.listState(db,workspace.id);task=state.tasks.find(item=>item.id===id);assert.equal(state.tasks.length,1);assert.equal(task.vaultSource.relativePath,"TODO/2026/Moved.md");writeFileSync(join(todo,"Moved.md"),"# Moved\n");const result=vault.scanVault(source.id,actor,db);task=core.listState(db,workspace.id).tasks.find(item=>item.id===id);assert.equal(result.removedTasks,1);assert.equal(task.archived,true);assert.equal(db.prepare("SELECT COUNT(*) count FROM calendar_event_mappings").get().count,0)}finally{db.close();rmSync(dir,{recursive:true,force:true})}});

