test("analytics is opt-in, allowlisted, content-safe, and erasable",async()=>{
  const dir=temp(),{openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),analytics=await import("../server/analytics.mjs"),db=openDatabase(join(dir,"test.sqlite"));
  try{const user=await auth.ensureOwner({email:"owner@example.com",password:"correct horse battery staple"},db);assert.deepEqual(analytics.recordAnalytics(user.id,{event:"navigation",properties:{area:"vault"}},db),{recorded:false});analytics.setAnalyticsEnabled(user.id,true,db);assert.deepEqual(analytics.recordAnalytics(user.id,{event:"operation",properties:{kind:"search",outcome:"success",durationMs:12}},db),{recorded:true});assert.equal(analytics.analyticsStatus(user.id,db).eventCount,1);for(const input of [{event:"operation",properties:{noteBody:"private text"}},{event:"navigation",properties:{area:"private note title"}},{event:"capture",properties:{outcome:"success"}},{event:"navigation",properties:{area:"vault"},noteBody:"private text"}])assert.throws(()=>analytics.recordAnalytics(user.id,input,db),/allowlisted|Invalid/);assert.equal(db.prepare("SELECT properties_json FROM analytics_events").get().properties_json.includes("private"),false);assert.equal(analytics.deleteAnalytics(user.id,db).deleted,1);assert.equal(analytics.setAnalyticsEnabled(user.id,false,db).enabled,false);assert.deepEqual(analytics.recordAnalytics(user.id,{event:"navigation",properties:{area:"vault"}},db),{recorded:false})}finally{db.close();rmSync(dir,{recursive:true,force:true})}
});

test("knowledge graph syncs typed relationships without private bodies",async()=>{const dir=temp(),{openDatabase}=await import("../server/db.mjs"),core=await import("../server/core.mjs"),graph=await import("../server/knowledge-graph.mjs"),db=openDatabase(join(dir,"test.sqlite"));try{const project=core.saveProject({name:"Graph project",summary:"private project summary"},db),task=core.saveTask({title:"Graph task",project:"Graph project",due:"Today"},db),first=core.saveNote({title:"First graph note",content:"private body alpha",tags:[]},db),second=core.saveNote({title:"Second graph note",content:"[[First graph note]] private body beta",tags:[]},db),capture=core.createCapture({text:"private capture body",source:"text",sourceLabel:"Typed capture"},db);const synced=graph.syncKnowledgeGraph(db);assert.ok(synced.nodes>=5);assert.ok(synced.edges>=2);const neighborhood=graph.queryKnowledgeGraph({root:`project:${project.id}`},db);assert.ok(neighborhood.nodes.some(node=>node.id===`task:${task.id}`));assert.ok(neighborhood.edges.some(edge=>edge.provenance==="tasks.project"));assert.equal(graph.queryKnowledgeGraph({limit:9999},db).meta.limit,500);const path=graph.knowledgePath(`note:${second.id}`,`note:${first.id}`,db);assert.equal(path.edges[0].kind,"links-to");const serialized=JSON.stringify(graph.queryKnowledgeGraph({},db));assert.doesNotMatch(serialized,/private body|private project summary|private capture body/);assert.match(serialized,/Typed capture/);db.prepare("DELETE FROM notes WHERE id=?").run(second.id);graph.syncKnowledgeGraph(db);assert.equal(db.prepare("SELECT id FROM knowledge_nodes WHERE id=?").get(`note:${second.id}`),undefined);assert.ok(db.prepare("SELECT id FROM knowledge_nodes WHERE id=?").get(`capture:${capture.id}`))}finally{db.close();rmSync(dir,{recursive:true,force:true})}});

test("custom dashboards validate, version, reorder, duplicate, and derive workspace data",async()=>{const dir=temp(),{openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),collaboration=await import("../server/collaboration.mjs"),core=await import("../server/core.mjs"),dashboards=await import("../server/dashboards.mjs"),db=openDatabase(join(dir,"test.sqlite"));try{const owner=await auth.ensureOwner({email:"owner@example.com",password:"correct horse battery staple"},db),workspace=collaboration.createWorkspace(owner.id,{name:"Dashboard"},db),other=collaboration.createWorkspace(owner.id,{name:"Other"},db);core.saveTask({title:"Dashboard task",project:"Inbox",due:"Today"},db,{id:owner.id,workspaceId:workspace.id});core.saveTask({title:"Other task",project:"Inbox",due:"Today"},db,{id:owner.id,workspaceId:other.id});const layout=[{id:"tasks",type:"tasks",title:"Priority tasks",x:0,y:0,w:6,h:2},{id:"notes",type:"notes",title:"Recent notes",x:6,y:0,w:6,h:2}],first=dashboards.saveDashboard(owner.id,workspace.id,{name:"Focus",layout},db);assert.equal(first.version,1);assert.deepEqual(dashboards.dashboardView(workspace.id,first.id,db).widgets[0].data.map(row=>row.title),["Dashboard task"]);assert.throws(()=>dashboards.saveDashboard(owner.id,workspace.id,{name:"Overlap",layout:[layout[0],{...layout[1],x:5}]},db),/overlap/);const updated=dashboards.saveDashboard(owner.id,workspace.id,{id:first.id,version:1,name:"Focus now",layout:[{...layout[0],w:12}]},db);assert.equal(updated.version,2);assert.throws(()=>dashboards.saveDashboard(owner.id,workspace.id,{id:first.id,version:1,name:"Stale",layout:[]},db),error=>error.code==="VERSION_CONFLICT");assert.throws(()=>dashboards.saveDashboard(owner.id,other.id,{id:first.id,version:2,name:"Cross",layout:[]},db),error=>error.status===404);const copy=dashboards.duplicateDashboard(owner.id,workspace.id,first.id,db);assert.equal(copy.name,"Focus now copy");const reordered=dashboards.reorderDashboards(workspace.id,[copy.id,first.id],db);assert.deepEqual(reordered.map(item=>item.id),[copy.id,first.id]);assert.equal(dashboards.listDashboards(other.id,db).length,0);assert.throws(()=>dashboards.deleteDashboard(workspace.id,first.id,1,db),error=>error.code==="VERSION_CONFLICT");assert.equal(dashboards.deleteDashboard(workspace.id,first.id,reordered[1].version,db).deleted,1)}finally{db.close();rmSync(dir,{recursive:true,force:true})}});

test("repository IDE confines paths, versions edits, runs allowlisted commands, and manages Git",async()=>{const dir=temp(),outside=temp(),fs=require("node:fs"),{execFileSync}=require("node:child_process"),{openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),repositories=await import("../server/repositories.mjs"),db=openDatabase(join(dir,"test.sqlite"));try{fs.writeFileSync(join(dir,"README.md"),"first\n");fs.writeFileSync(join(outside,"secret.txt"),"secret\n");fs.symlinkSync(join(outside,"secret.txt"),join(dir,"escape"));execFileSync("git",["init","-q",dir]);execFileSync("git",["-C",dir,"config","user.email","test@example.com"]);execFileSync("git",["-C",dir,"config","user.name","Test"]);execFileSync("git",["-C",dir,"add","README.md"]);execFileSync("git",["-C",dir,"commit","-q","-m","initial"]);const owner=await auth.ensureOwner({email:"owner@example.com",password:"correct horse battery staple"},db),repo=repositories.registerRepository(owner.id,{path:dir,name:"Sandbox"},[dir],db),opened=repositories.browseRepository(owner.id,repo.id,"README.md",db);assert.equal(opened.file.content,"first\n");assert.throws(()=>repositories.browseRepository(owner.id,repo.id,"../secret.txt",db),error=>error.code==="PATH_FORBIDDEN");assert.throws(()=>repositories.browseRepository(owner.id,repo.id,"escape",db),error=>error.code==="PATH_FORBIDDEN");const saved=repositories.saveFiles(owner.id,repo.id,[{path:"README.md",expectedHash:opened.file.hash,content:"second\n"}],db);assert.equal(saved.files[0].content,"second\n");assert.throws(()=>repositories.saveFiles(owner.id,repo.id,[{path:"README.md",expectedHash:opened.file.hash,content:"stale\n"}],db),error=>error.code==="VERSION_CONFLICT");assert.equal((await repositories.runRepositoryCommand(owner.id,repo.id,"status",{isolate:false},db)).exitCode,0);await assert.rejects(()=>repositories.runRepositoryCommand(owner.id,repo.id,"shell",{isolate:false},db),/allowlisted/);repositories.mutateGit(owner.id,repo.id,{action:"commit",message:"Update readme",paths:["README.md"]},db);const history=repositories.repositoryGit(owner.id,repo.id,db).history;assert.equal(history[0].subject,"Update readme");repositories.mutateGit(owner.id,repo.id,{action:"revert",ref:history[0].ref},db);assert.equal(fs.readFileSync(join(dir,"README.md"),"utf8"),"first\n");assert.ok(db.prepare("SELECT 1 FROM audit_events WHERE object_type='repository' AND action='revert'").get())}finally{db.close();rmSync(dir,{recursive:true,force:true});rmSync(outside,{recursive:true,force:true})}});

test("plugin marketplace verifies manifests, installs transactionally, isolates runs, and survives offline catalogs",async()=>{const dir=temp(),catalog=join(dir,"catalog"),pluginsDir=join(dir,"installed"),fs=require("node:fs"),{openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),plugins=await import("../server/plugins.mjs"),db=openDatabase(join(dir,"test.sqlite"));const make=(folder,version,permissions=["tasks:read","notifications:write"],code='let data="";for await(const chunk of process.stdin)data+=chunk;const value=JSON.parse(data);process.stdout.write(JSON.stringify({seen:value.context.tasks.length,notifications:[{title:"Plugin complete"}]}));')=>{const path=join(catalog,folder);fs.mkdirSync(path,{recursive:true});fs.writeFileSync(join(path,"index.mjs"),code);const manifest={apiVersion:1,id:"dev.noema.browser",name:"Browser plugin",version,description:"Test plugin",entry:"index.mjs",permissions,integrity:plugins.packageIntegrity(path),noema:{minimumVersion:"0.1.0"}};fs.writeFileSync(join(path,"manifest.json"),JSON.stringify(manifest));return path};try{fs.mkdirSync(catalog,{recursive:true});fs.mkdirSync(pluginsDir,{recursive:true});const firstPath=make("browser-1","1.0.0"),badPath=make("malicious","1.0.0",["secrets:read"]);const owner=await auth.ensureOwner({email:"owner@example.com",password:"correct horse battery staple"},db);let market=plugins.listPluginMarketplace(owner.id,[catalog],db),entry=market.catalog.find(item=>item.manifest?.version==="1.0.0");assert.equal(entry.manifest.id,"dev.noema.browser");assert.equal(market.catalog.find(item=>item.error)?.error.code,"INVALID_MANIFEST");const inspected=plugins.inspectPlugin([catalog],entry.catalogId,entry.manifest.id,"1.0.0");assert.match(inspected.files[0].source,/process\.stdin/);let installed=plugins.installPlugin(owner.id,{catalogId:entry.catalogId,pluginId:entry.manifest.id,version:"1.0.0"},[catalog],pluginsDir,db);assert.equal(installed.version,"1.0.0");db.prepare("INSERT INTO tasks(id,title,project,due,priority,created_at,updated_at) VALUES(?,?,?,?,?,?,?)").run("plugin-task","Plugin task","Inbox","Today","Medium",new Date().toISOString(),new Date().toISOString());const run=await plugins.runPlugin(owner.id,installed.id,{},db);assert.equal(run.effects.notifications,1);assert.equal(run.result.seen,1);assert.ok(db.prepare("SELECT 1 FROM notifications WHERE title='Plugin complete'").get());make("browser-2","1.1.0");entry=plugins.listPluginMarketplace(owner.id,[catalog],db).catalog.find(item=>item.manifest?.version==="1.1.0");installed=plugins.installPlugin(owner.id,{catalogId:entry.catalogId,pluginId:entry.manifest.id,version:"1.1.0"},[catalog],pluginsDir,db);assert.equal(installed.version,"1.1.0");fs.writeFileSync(join(badPath,"manifest.json"),JSON.stringify({...JSON.parse(fs.readFileSync(join(firstPath,"manifest.json"))),version:"1.2.0",integrity:"sha256-invalid"}));assert.throws(()=>plugins.installPlugin(owner.id,{catalogId:entry.catalogId,pluginId:entry.manifest.id,version:"1.2.0"},[catalog],pluginsDir,db),/not found|integrity/);assert.equal(plugins.listPluginMarketplace(owner.id,[],db).installed[0].version,"1.1.0");plugins.setPluginEnabled(owner.id,installed.id,false,db);await assert.rejects(()=>plugins.runPlugin(owner.id,installed.id,{},db),/Enabled plugin/);plugins.setPluginEnabled(owner.id,installed.id,true,db);assert.equal(plugins.uninstallPlugin(owner.id,installed.id,pluginsDir,db).deleted,1);assert.equal(plugins.listPluginMarketplace(owner.id,[],db).installed.length,0)}finally{db.close();rmSync(dir,{recursive:true,force:true})}});

test("workspace invitations, roles, presence, comments, conflicts, and revocation enforce isolation",async()=>{const dir=temp(),{openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),collaboration=await import("../server/collaboration.mjs"),db=openDatabase(join(dir,"test.sqlite"));try{const owner=await auth.ensureOwner({email:"owner@example.com",password:"correct horse battery staple"},db),member=await auth.ensureOwner({email:"member@example.com",password:"another correct horse staple"},db),workspace=collaboration.createWorkspace(owner.id,{name:"Shared launch"},db),personal=collaboration.ensureDefaultWorkspace(member.id,db);assert.throws(()=>collaboration.workspaceAccess(member.id,workspace.id,"viewer",db),error=>error.status===404);const invite=collaboration.createInvitation(owner.id,workspace.id,{email:member.email,role:"viewer",expiresHours:1},db);assert.equal(collaboration.acceptInvitation(member.id,member.email,invite.token,db).role,"viewer");assert.throws(()=>collaboration.acceptInvitation(member.id,member.email,invite.token,db),error=>error.code==="INVITATION_UNAVAILABLE");assert.throws(()=>collaboration.saveComment(member.id,workspace.id,{objectType:"note",objectId:"n1",body:"Blocked"},db),error=>error.code==="WORKSPACE_ROLE_REQUIRED");collaboration.changeMember(owner.id,workspace.id,member.id,{role:"editor"},db);const comment=collaboration.saveComment(member.id,workspace.id,{objectType:"note",objectId:"n1",body:"Review this"},db);assert.equal(comment.actor,member.email);assert.equal(collaboration.listComments(owner.id,workspace.id,"note","n1",db).length,1);assert.equal(collaboration.updatePresence(member.id,workspace.id,{location:"vault",objectType:"note",objectId:"n1"},db).length,1);const conflict=collaboration.recordConflict(workspace.id,member.id,"note","n1",1,{content:"owner"},{content:"member"},db);assert.equal(collaboration.listConflicts(owner.id,workspace.id,db)[0].id,conflict.id);const registration=collaboration.createInvitation(owner.id,workspace.id,{email:"new@example.com",role:"editor"},db),created=await collaboration.registerWithInvitation({token:registration.token,email:"new@example.com",password:"new correct horse password"},db);assert.equal(created.role,"editor");const expired=collaboration.createInvitation(owner.id,workspace.id,{email:"late@example.com",role:"viewer"},db);db.prepare("UPDATE workspace_invitations SET expires_at='2000-01-01T00:00:00.000Z' WHERE id=?").run(expired.id);assert.throws(()=>collaboration.invitationForToken(expired.token,db),error=>error.code==="INVITATION_UNAVAILABLE");collaboration.changeMember(owner.id,workspace.id,member.id,{revoke:true},db);assert.throws(()=>collaboration.listComments(member.id,workspace.id,"note","n1",db),error=>error.status===404);assert.equal(collaboration.workspaceAccess(member.id,personal.id,"owner",db).role,"owner");assert.ok(db.prepare("SELECT 1 FROM audit_events WHERE workspace_id=? AND actor_id=? AND action='comment'").get(workspace.id,member.id))}finally{db.close();rmSync(dir,{recursive:true,force:true})}});

test("canonical objects, conflicts, audits, and assets stay inside their workspace",async()=>{const dir=temp(),{openDatabase}=await import("../server/db.mjs"),auth=await import("../server/auth.mjs"),collaboration=await import("../server/collaboration.mjs"),core=await import("../server/core.mjs"),objects=await import("../server/objects.mjs"),db=openDatabase(join(dir,"test.sqlite")),config={dataDir:dir,objectsDir:join(dir,"objects"),jobsDir:join(dir,"jobs")};require("node:fs").mkdirSync(config.objectsDir,{recursive:true});require("node:fs").mkdirSync(config.jobsDir,{recursive:true});try{const owner=await auth.ensureOwner({email:"scope@example.com",password:"correct horse battery staple"},db),one=collaboration.createWorkspace(owner.id,{name:"One"},db),two=collaboration.createWorkspace(owner.id,{name:"Two"},db),a1={id:owner.id,workspaceId:one.id},a2={id:owner.id,workspaceId:two.id},task=core.saveTask({title:"Only one",project:"Inbox",due:"Today"},db,a1),note=core.saveNote({title:"Private",content:"workspace secret"},db,a1);core.saveTask({title:"Only two",project:"Inbox",due:"Today"},db,a2);assert.deepEqual(core.listState(db,one.id).tasks.map(row=>row.title),["Only one"]);assert.deepEqual(core.listState(db,two.id).tasks.map(row=>row.title),["Only two"]);assert.equal(core.searchNotes("secret",db,two.id).length,0);assert.throws(()=>core.saveTask({...task,title:"Cross",version:task.version},db,a2),error=>error.status===404);assert.throws(()=>core.saveNote({...note,content:"stale",version:0},db,a1),error=>error.status===409&&!!error.conflictId);const conflict=collaboration.listConflicts(owner.id,one.id,db)[0];assert.equal(conflict.current.content,"workspace secret");assert.equal(conflict.proposed.content,"stale");assert.ok(core.listAuditEvents(20,db,one.id).every(event=>!core.listAuditEvents(20,db,two.id).some(other=>other.id===event.id)));const stream=()=>require("node:stream").Readable.from(["same bytes"]),asset=await objects.storeAsset({stream:stream(),name:"one.txt",mime:"text/plain"},config,db,one.id);assert.equal(objects.getAsset(asset.id,db,two.id),null);await objects.storeAsset({stream:stream(),name:"two.txt",mime:"text/plain"},config,db,two.id);assert.equal(objects.getAsset(asset.id,db,two.id).id,asset.id);const capture=core.createCapture({text:"attached",assetIds:[asset.id]},db,a1);assert.equal(capture.assets.length,1);assert.throws(()=>core.createCapture({text:"wrong",assetIds:[asset.id]},db,{id:owner.id,workspaceId:collaboration.createWorkspace(owner.id,{name:"Three"},db).id}),error=>error.status===404)}finally{db.close();rmSync(dir,{recursive:true,force:true})}});

